/// invalid, or (with no custom `cache_dir` configured) the platform reports none
/// and `TREE_SITTER_LANGUAGE_PACK_CACHE_DIR` is unset. This crate no longer falls
/// back to the temporary directory for the latter case — see #101 H2.
pub fn cache_dir() Error![]u8 {
    const _result = c.ts_pack_cache_dir();
    if (c.ts_pack_last_error_code() != 0) {
        return _error_with_message(Error);
    }
    if (_result == null) {
        return _error_with_message(Error);
    }
    const _result_len = c.ts_pack_cache_dir_len();
    return blk: {
        if (_result == null) return error.UnknownFfiError;
        const slice = _result[0.._result_len];
        defer _free_string(_result);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

