    // Vec/Map parameters are passed as JSON strings across the FFI boundary.
    const languages_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{languages}, 0);
    defer std.heap.c_allocator.free(languages_z);
    _ = c.ts_pack_prefetch(languages_z);
    if (c.ts_pack_last_error_code() != 0) {
        return _error_with_message(Error);
    }
    return;
}

/// Process source code and extract file intelligence using the global registry.
///
/// Parses the source with tree-sitter and extracts metrics, structure, imports,
/// exports, comments, docstrings, symbols, diagnostics, and/or chunks based on
/// the flags set in `ProcessConfig`.
///
/// **Errors:**
///
/// Returns `Error.InvalidRange` if the config carries a zero-valued limit or
/// the source exceeds `ProcessConfig.max_source_bytes`,
/// `Error.ParseTimeout` if the parse exceeds
/// `ProcessConfig.parse_timeout_ms`, `Error.LanguageNotFound` if the
/// language is unknown, or `Error.ParseFailed` if parsing yields no tree.
pub fn process(source: []const u8, config: []const u8) Error![]u8 {
    const source_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{source}, 0);
    defer std.heap.c_allocator.free(source_z);
    const config_z = try std.fmt.allocPrintSentinel(std.heap.c_allocator, "{s}", .{config}, 0);
    defer std.heap.c_allocator.free(config_z);
    const config_handle = c.ts_pack_process_config_from_json(config_z);
    if (config_handle == 0) return _error_with_message(Error);
    defer c.ts_pack_process_config_free(config_handle);
    const _result = c.ts_pack_process(source_z, config_handle);
    if (c.ts_pack_last_error_code() != 0) {
        return _error_with_message(Error);
    }
    return blk: {
        if (_result == 0) return error.UnknownFfiError;
        const value = _result;
        defer c.ts_pack_process_result_free(value);
        const _json_ptr = c.ts_pack_process_result_to_json(value);
        if (_json_ptr == null) return error.UnknownFfiError;
        defer _free_string(_json_ptr);
        const slice = std.mem.sliceTo(_json_ptr, 0);
        const owned = try std.heap.c_allocator.dupe(u8, slice);
        break :blk owned;
    };
}

/// Create a new download manager for the given version.
///
/// **Errors:**
///
/// Returns `Error.Download` if `version` is empty, contains a path
/// separator or `..`, or contains a character outside `[A-Za-z0-9.+-]` — see
/// `validate_version` — or if no cache directory can be resolved (see
/// `Self.default_cache_dir`).
pub fn new_download_manager(version: []const u8) error{ OutOfMemory, UnknownFfiError }!DownloadManager {
    const version_z = try std.heap.c_allocator.dupeZ(u8, version);
    defer std.heap.c_allocator.free(version_z);
    const _handle = c.ts_pack_download_manager_new(version_z.ptr);
    if (_handle == 0) return error.UnknownFfiError;
    return .{ ._handle = _handle };
}

/// Manages downloading and caching of pre-built parser shared libraries.
pub const DownloadManager = struct {
    _handle: u64,

    /// List languages that are already downloaded and cached.
    ///
    /// Derived from the on-disk cache filenames, one canonical name per file, plus
    /// every alias that resolves to it (via `aliases_for`) — so
    /// this list agrees with the user-facing
    /// `LanguageRegistry.available_languages`
    /// about which names are "available"; both report `"shell"` once `bash` is
    /// cached, for example. A previous version reported canonical names only,
    /// which could never agree with `available_languages()`. See #107.
    ///
    /// Returns an empty list if the cache directory does not exist. If it exists
    /// but cannot be read (e.g. a permission error), also returns an empty list —
    /// changing this to a `Result` would be a breaking change across every
    /// language binding — but logs a `tracing.warn!` so the failure is not
    /// silently indistinguishable from "nothing installed".
    pub fn installed_languages(self: *DownloadManager) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_download_manager_installed_languages(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.ts_pack_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Download the platform bundle and extract every library file it contains.
    ///
    /// Unlike `Self.ensure_languages`, this does not check the manifest language list
    /// against archive contents — it simply extracts all `.so`/`.dylib`/`.dll` files
    /// from the bundle. Languages in the manifest that are missing from the archive
    /// are silently ignored rather than returning an error.
    ///
    /// Returns the number of library files extracted (including those already cached).
    pub fn download_all_best_effort(self: *DownloadManager) (Error || error{ OutOfMemory, HandleClosed })!u64 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_download_manager_download_all_best_effort(handle);
        if (c.ts_pack_last_error_code() != 0) {
            return _error_with_message(Error);
        }
        return _result;
    }

    /// Remove all cached parser libraries.
    ///
    /// Acquires the cross-process lock so `clean_cache` cannot race a concurrent
    /// downloader (avoids Windows sharing-violation errors against an in-flight
    /// bundle write). The `.download.lock` file itself is **not** removed — it is
    /// permanent infrastructure; deleting it could allow a concurrent process that
    /// already opened the file to continue holding a stale lock handle while a new
    /// process opens a fresh inode, breaking the mutual-exclusion guarantee.
    pub fn clean_cache(self: *DownloadManager) (Error || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        _ = c.ts_pack_download_manager_clean_cache(handle);
        if (c.ts_pack_last_error_code() != 0) {
            return _error_with_message(Error);
        }
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *DownloadManager) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.ts_pack_download_manager_free(handle);
    }
};

pub const Language = struct {
