/// When the `dynamic-loading` feature is enabled, the registry also knows
/// about dynamically loadable grammars and will load them on demand.
pub fn new_language_registry() error{UnknownFfiError}!LanguageRegistry {
    const _handle = c.ts_pack_language_registry_new();
    if (_handle == 0) return error.UnknownFfiError;
    return .{ ._handle = _handle };
}

pub fn default_language_registry() error{UnknownFfiError}!LanguageRegistry {
    const _handle = c.ts_pack_language_registry_default();
    if (_handle == 0) return error.UnknownFfiError;
    return .{ ._handle = _handle };
}

/// Thread-safe registry of tree-sitter language parsers.
///
/// Manages both statically compiled and dynamically loaded language grammars.
/// Use `LanguageRegistry.new()` for the default registry, or access the
/// global instance via the module-level convenience functions
/// (`get_language`, `available_languages`, etc.).
pub const LanguageRegistry = struct {
    _handle: u64,

    /// Get a tree-sitter `Language` by name.
    ///
    /// Resolves aliases (e.g., `"shell"` -> `"bash"`, `"makefile"` -> `"make"`),
    /// then looks up the language in the static table. When the `dynamic-loading`
    /// feature is enabled, falls back to loading a shared library on demand.
    ///
    /// **Errors:**
    ///
    /// Returns `Error.LanguageNotFound` if the name (after alias resolution)
    /// does not match any known grammar.
    pub fn get_language(self: *LanguageRegistry, name: []const u8) (Error || error{ OutOfMemory, HandleClosed })!Language {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const name_z = try std.heap.c_allocator.dupeZ(u8, name);
        defer std.heap.c_allocator.free(name_z);
        const _result = c.ts_pack_language_registry_get_language(handle, name_z);
        if (c.ts_pack_last_error_code() != 0) {
            return _error_with_message(Error);
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk Language{ ._handle = _result };
        };
    }

    /// List all available language names, sorted and deduplicated.
    ///
    /// Includes statically compiled languages, dynamically loadable languages
    /// (if the `dynamic-loading` feature is enabled), and all configured aliases.
    pub fn available_languages(self: *LanguageRegistry) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_language_registry_available_languages(handle);
        return blk: {
            const value = _result orelse return error.OutOfMemory;
            defer c.ts_pack_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Check whether this language can be parsed right now, without downloading.
    ///
    /// Resolves aliases, then answers from exactly the lookup
    /// `get_language` performs: the statically compiled
    /// table, the already-loaded dynamic grammars, and the parser shared
    /// libraries present in the primary and extra (download-cache) library
    /// directories. It never performs network I/O.
    ///
    /// A previous implementation consulted only the statically compiled table.
    /// That table is empty in every build that does not set `TSLP_LANGUAGES`,
    /// so the function answered `false` for languages this registry parses
    /// perfectly well.
    ///
    /// Contrast `has_language`, which is also `true` for a
    /// grammar that is merely *known to the manifest* and would have to be
    /// downloaded first. The pair distinguishes "we can parse it offline, now"
    /// from "we recognise the name".
    ///
    /// The first `true` answer for a dynamic grammar loads its shared library:
    /// loading is the only way to know the grammar is usable, since a truncated
    /// or wrong-architecture library exists on disk but cannot parse. Loads are
    /// cached process-wide, so repeat calls are cheap.
    pub fn has_parser(self: *LanguageRegistry, name: []const u8) error{ OutOfMemory, HandleClosed }!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const name_z = try std.heap.c_allocator.dupeZ(u8, name);
        defer std.heap.c_allocator.free(name_z);
        const _result = c.ts_pack_language_registry_has_parser(handle, name_z);
        return _result != 0;
    }

    /// Check whether a language is available by name or alias.
    ///
    /// Returns `true` if the language can be loaded, either from the static
    /// table or from a dynamic library on disk.
    ///
    /// Every branch is one more way to answer `true`, so they are ordered
    /// cheapest-first and the filesystem is only consulted once every in-memory
    /// source has said no. Probing the loaded-grammar map and the manifest ahead
    /// of the `stat` calls is what keeps this off the syscall path for the
    /// languages a process actually uses.
    pub fn has_language(self: *LanguageRegistry, name: []const u8) error{ OutOfMemory, HandleClosed }!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const name_z = try std.heap.c_allocator.dupeZ(u8, name);
        defer std.heap.c_allocator.free(name_z);
        const _result = c.ts_pack_language_registry_has_language(handle, name_z);
        return _result != 0;
    }

    /// Return the total number of available languages (including aliases).
    ///
    /// Counts the same set `available_languages`
    /// lists, without materialising or sorting it.
    pub fn language_count(self: *LanguageRegistry) error{HandleClosed}!u64 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_language_registry_language_count(handle);
        return _result;
    }

    /// Parse source code and extract file intelligence based on config in a single pass.
    ///
    /// **Errors:**
    ///
    /// Returns `Error.InvalidRange` if the config is invalid (see
    /// `ProcessConfig.validate`) or if the source
    /// exceeds the configured
    /// `max_source_bytes`;
    /// `Error.LanguageNotFound` if the language is unknown; or
    /// `Error.ParseFailed` if parsing produces no tree.
    pub fn process(self: *LanguageRegistry, source: []const u8, config: []const u8) (Error || error{ OutOfMemory, HandleClosed })![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const source_z = try std.heap.c_allocator.dupeZ(u8, source);
        defer std.heap.c_allocator.free(source_z);
        const config_z = try std.heap.c_allocator.dupeZ(u8, config);
        defer std.heap.c_allocator.free(config_z);
        const config_handle = c.ts_pack_process_config_from_json(config_z.ptr);
        if (config_handle == 0) return error.UnknownFfiError;
        defer c.ts_pack_process_config_free(config_handle);
        const _result = c.ts_pack_language_registry_process(handle, source_z, config_handle);
        if (c.ts_pack_last_error_code() != 0) {
            return _error_with_message(Error);
        }
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            const value = _result;
            defer c.ts_pack_process_result_free(value);
            const _json_ptr = c.ts_pack_process_result_to_json(value) orelse return error.OutOfMemory;
            defer c.ts_pack_free_string(_json_ptr);
            const _json_slice = std.mem.span(_json_ptr);
            const owned = try std.heap.c_allocator.dupe(u8, _json_slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *LanguageRegistry) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.ts_pack_language_registry_free(handle);
    }
};

/// A single syntax node within a `Tree`.
///
/// Nodes hold a strong reference to their parent tree so they remain valid
/// regardless of how the tree is moved or stored at the FFI boundary.
pub const Node = struct {
    _handle: u64,

    /// Return the node's kind name (e.g. `"function_definition"`).
