    /// text accessor.
    pub fn byte_range(self: *Node) error{ OutOfMemory, HandleClosed }![]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_node_byte_range(handle);
