    const _handle = c.ts_pack_parser_new();
    if (_handle == 0) return error.UnknownFfiError;
    return .{ ._handle = _handle };
}

pub fn default_parser() error{UnknownFfiError}!Parser {
    const _handle = c.ts_pack_parser_default();
    if (_handle == 0) return error.UnknownFfiError;
    return .{ ._handle = _handle };
}

/// A tree-sitter parser configured for one language at a time.
pub const Parser = struct {
    _handle: u64,

    /// Refuse to parse sources longer than `max_bytes`.
    ///
    /// `null` (the default) means no limit. Over-limit input makes
    /// `parse` and `parse_bytes` return
    /// `null` after emitting a `WARN`; input is never silently truncated.
    ///
    /// See `RECOMMENDED_MAX_SOURCE_BYTES`.
    pub fn set_max_source_bytes(self: *Parser, max_bytes: ?u64) error{HandleClosed}!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        c.ts_pack_parser_set_max_source_bytes(handle, if (max_bytes) |v| v else std.math.maxInt(u64));
    }

    /// Cancel a parse that exceeds `timeout_ms` milliseconds of wall clock.
    ///
    /// `null` (the default) means no budget. Cancellation runs through
    /// tree-sitter's parse progress callback, so it is granular to that
    /// callback's interval rather than exact.
    ///
    /// See `RECOMMENDED_PARSE_TIMEOUT_MS`.
    pub fn set_parse_timeout_ms(self: *Parser, timeout_ms: ?u64) error{HandleClosed}!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        c.ts_pack_parser_set_parse_timeout_ms(handle, if (timeout_ms) |v| v else std.math.maxInt(u64));
    }

    /// Configure the parser to use the language identified by name (e.g. `"python"`).
    ///
    /// Resolves the language through the global registry — auto-downloading
    /// if necessary, when the `download` feature is enabled.
    ///
    /// **Errors:**
    ///
    /// Returns `Error.LanguageNotFound` if the language is not recognized,
    /// or `Error.ParserSetup` if the language ABI is incompatible.
    pub fn set_language(self: *Parser, name: []const u8) (Error || error{ OutOfMemory, HandleClosed })!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const name_z = try std.heap.c_allocator.dupeZ(u8, name);
        defer std.heap.c_allocator.free(name_z);
        _ = c.ts_pack_parser_set_language(handle, name_z);
        if (c.ts_pack_last_error_code() != 0) {
            return _error_with_message(Error);
        }
    }

    /// Parse a UTF-8 source string.
    ///
    /// Returns `null` if no language is set, if the parse was cancelled by the
    /// configured timeout, or if the source
    /// exceeds the configured size limit. Each
    /// non-parse outcome is logged, so an empty result is never silent.
    ///
    /// # Concurrency
    ///
    /// Parsing runs fully in parallel across threads for almost every language — no lock is
    /// taken. The exception is the small set of grammars whose external scanner keeps mutable
    /// process-global state (currently just `properties`): parses of that language are
    /// serialized against each other through an internal per-language lock, so that concurrent
    /// threads can't corrupt shared scanner state. Every other language is unaffected by that
    /// lock and never waits on it.
    pub fn parse(self: *Parser, source: []const u8) error{ OutOfMemory, HandleClosed }!?Tree {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const source_z = try std.heap.c_allocator.dupeZ(u8, source);
        defer std.heap.c_allocator.free(source_z);
        const _result = c.ts_pack_parser_parse(handle, source_z);
        return if (_result == 0) null else Tree{ ._handle = _result };
    }

    /// Parse a raw byte slice.
    ///
    /// Same outcomes as `parse`, including the concurrency behaviour documented
    /// there.
    pub fn parse_bytes(self: *Parser, source: []const u8) error{HandleClosed}!?Tree {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_parser_parse_bytes(handle, source.ptr, source.len);
        return if (_result == 0) null else Tree{ ._handle = _result };
    }

    /// Reset internal state. The next call to `parse` will
    /// not be incremental.
    pub fn reset(self: *Parser) error{HandleClosed}!void {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        c.ts_pack_parser_reset(handle);
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *Parser) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.ts_pack_parser_free(handle);
    }
};

/// A parsed syntax tree. Cheap to clone (refcount bump).
pub const Tree = struct {
    _handle: u64,

    /// Return the root `Node` of this tree.
    pub fn root_node(self: *Tree) error{ OutOfMemory, HandleClosed }!Node {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_root_node(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk Node{ ._handle = _result };
        };
    }

    /// Return a `TreeCursor` positioned at the root.
    pub fn walk(self: *Tree) error{ OutOfMemory, HandleClosed }!TreeCursor {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_walk(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk TreeCursor{ ._handle = _result };
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *Tree) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.ts_pack_tree_free(handle);
    }
};

/// A cursor for traversing a `Tree`.
pub const TreeCursor = struct {
    _handle: u64,

    /// Return the `Node` at the cursor's current position.
    pub fn node(self: *TreeCursor) error{ OutOfMemory, HandleClosed }!Node {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_cursor_node(handle);
        return blk: {
            if (_result == 0) return error.OutOfMemory;
            break :blk Node{ ._handle = _result };
        };
    }

    /// Move the cursor to the first child of the current node.
    /// Returns `true` if a child existed.
    pub fn goto_first_child(self: *TreeCursor) error{HandleClosed}!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_cursor_goto_first_child(handle);
        return _result != 0;
    }

    /// Move the cursor to the parent of the current node.
    /// Returns `true` if a parent existed.
    pub fn goto_parent(self: *TreeCursor) error{HandleClosed}!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_cursor_goto_parent(handle);
        return _result != 0;
    }

    /// Move the cursor to the next sibling of the current node.
    /// Returns `true` if a sibling existed.
    pub fn goto_next_sibling(self: *TreeCursor) error{HandleClosed}!bool {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_cursor_goto_next_sibling(handle);
        return _result != 0;
    }

    /// Return the field name for the current node, if any.
    pub fn field_name(self: *TreeCursor) error{ OutOfMemory, HandleClosed }!?[]u8 {
        const handle = self._handle;
        if (handle == 0) return error.HandleClosed;
        const _result = c.ts_pack_tree_cursor_field_name(handle);
        return blk: {
            const value = _result orelse break :blk null;
            defer c.ts_pack_free_string(value);
            const slice = std.mem.span(value);
            const owned = try std.heap.c_allocator.dupe(u8, slice);
            break :blk owned;
        };
    }

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *TreeCursor) void {
        const handle = self._handle;
        if (handle == 0) return;
        self._handle = 0;
        c.ts_pack_tree_cursor_free(handle);
    }
};
